# /// script
# requires-python = ">=3.11"
# ///
"""Extract ARM's JTAG command loop with command-local function selection."""

import re
from pathlib import Path

from extract_swd_transfer import extract

SOURCE = Path("external/CMSIS-DAP/Firmware/Source/DAP.c")
TARGET = Path("src/jtag_transfer.h")
BANNER = '''/*
 * Copyright (c) 2013-2022 ARM Limited. All rights reserved.
 * SPDX-License-Identifier: Apache-2.0
 *
 * From CMSIS-DAP's DAP_JTAG_Transfer. Changes: command-local function selection,
 * unsigned operand decoding and initialized read data.
 */
/** GENERATED by tools/extract_jtag_transfer.py. Re-run after changing the CMSIS-DAP pin.
 *  Include after the command's resolve_transfers function (src/cjtag_dp.c).
 */
#ifndef JTAG_TRANSFER_H
#define JTAG_TRANSFER_H

#include "byte_io.h"
#include "hot.h"

'''


def render(text: str) -> str:
    body = "\n".join(extract(text, "DAP_JTAG_Transfer"))
    body = body.replace("static uint32_t DAP_JTAG_Transfer(", "COMMAND_PATH uint32_t JTAG_TransferCommand(", 1)
    body, initialized = re.subn(r"uint32_t\s+data;", "uint32_t  data = 0U;", body)
    body, resolved = re.subn(r"(  request_count = \*request\+\+;)",
                            r"  const struct jtag_transfer_fns fns = resolve_transfers();\n\n\1", body, count=1)
    body = re.sub(r"\bJTAG_Transfer\(", "fns.transfer(", body)
    body = re.sub(r"\bJTAG_IR\(", "fns.ir(", body)
    operands = (r"\(uint32_t\)\(\*\(request\+0\) <<  0\) \|\s*"
                r"\(uint32_t\)\(\*\(request\+1\) <<  8\) \|\s*"
                r"\(uint32_t\)\(\*\(request\+2\) << 16\) \|\s*"
                r"\(uint32_t\)\(\*\(request\+3\) << 24\)")
    body, decoded = re.subn(operands, "read_u32_le(request)", body)
    body = re.sub(r"\bNULL\b", "nullptr", body)
    if (initialized, resolved, decoded) != (1, 1, 2):
        raise ValueError(f"upstream JTAG loop changed: {(initialized, resolved, decoded)}")
    return BANNER + body + "\n\n#endif\n"


if __name__ == "__main__":
    TARGET.write_text(render(SOURCE.read_text()))
    print(f"wrote {TARGET}")
